document.addEventListener("DOMContentLoaded",function(){function n(n){return n>=1e6?`$${(n/1e6).toFixed(1)}M`:n>=1e3?`$${(n/1e3).toFixed(0)}K`:n.toLocaleString("en-US",{style:"currency",currency:"USD",minimumFractionDigits:0,maximumFractionDigits:0})}function e(n){return`${n.toFixed(1)}%`}function s(n,e,s,t="info"){return`\n      <div class="insight-card ${t}">\n        <h6>${n}</h6>\n        <div class="metric-value">${e}</div>\n        <div class="metric-subtitle">${s}</div>\n      </div>\n    `}const t=document.getElementById("realestate-form"),a=document.getElementById("realestate-result");t&&t.addEventListener("submit",function(t){t.preventDefault();const i=parseInt(document.getElementById("agents-count").value),o=parseFloat(document.getElementById("office-setup").value),r=parseFloat(document.getElementById("legal-costs").value),l=parseFloat(document.getElementById("marketing-setup").value),d=parseFloat(document.getElementById("commission-rate").value),c=parseFloat(document.getElementById("monthly-deals").value),p=parseFloat(document.getElementById("avg-property-price").value),v=parseFloat(document.getElementById("agent-commission-share").value),g=parseFloat(document.getElementById("office-rent").value),m=parseFloat(document.getElementById("base-salaries").value),u=parseFloat(document.getElementById("marketing-costs").value),f=parseFloat(document.getElementById("other-costs").value);if(i<=0||d<=0||c<=0||p<=0)return a.innerHTML='<div class="error">Please enter valid values for all fields.</div>',void 0;const y=o+r+l,$=p*d/100,b=c*$,w=b*v/100,h=b-w,k=12*b,I=12*h,E=g+m+u+f,A=12*E,B=h-E,F=I-A,D=F/I*100,x=y/F,P=F/y*100,M=I/i,L=c/i,R=$,C=$-$*v/100;let O="info";F<0?O="warning":D>30&&(O="success");let S="info";P<20?S="warning":P>40&&(S="success");let T="info";L<2?T="warning":L>4&&(T="success"),a.innerHTML=`\n        <div class="business-plan-results">\n          <h3>🏢 Real Estate Agency Business Plan Analysis</h3>\n          \n          <div class="insight-cards">\n            ${s("💰 Total Investment",n(y),"Initial capital required","info")}\n            ${s("📈 Monthly Profit",n(B),`Margin: ${e(D)}`,O)}\n            ${s("⏱️ Payback Period",`${x.toFixed(1)} years`,`ROI: ${e(P)}`,x<=1.5?"success":"warning")}\n            ${s("📊 Deals per Agent",`${L.toFixed(1)}/month`,`Total: ${c} deals`,T)}\n          </div>\n\n          <div class="financial-breakdown">\n            <h4>💼 Detailed Financial Analysis</h4>\n            \n            <div class="section">\n              <h5>🏗️ Startup Costs</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Office lease & setup</span>\n                  <span>${n(o)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Licenses & legal costs</span>\n                  <span>${n(r)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Initial marketing & equipment</span>\n                  <span>${n(l)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Startup Investment</strong></span>\n                  <span><strong>${n(y)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💵 Annual Revenue</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Gross commission (${c} deals × ${n(R)})</span>\n                  <span>${n(k)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Agent payouts (${e(v)})</span>\n                  <span>-${n(12*w)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Net Agency Revenue</strong></span>\n                  <span><strong>${n(I)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💸 Monthly Expenses</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Office rent</span>\n                  <span>${n(g)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Base staff salaries</span>\n                  <span>${n(m)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Marketing & advertising</span>\n                  <span>${n(u)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Other expenses</span>\n                  <span>${n(f)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Monthly Expenses</strong></span>\n                  <span><strong>${n(E)}</strong></span>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card info">\n              <h6>🔄 Agent Efficiency</h6>\n              <div class="metric-subtitle">\n                Revenue per agent: <strong>${n(M)}/year</strong><br>\n                Deals per agent: <strong>${L.toFixed(1)}/month</strong><br>\n                Agency commission per deal: <strong>${n(C)}</strong>\n              </div>\n            </div>\n            <div class="insight-card ${F>0?"success":"warning"}">\n              <h6>📊 Deal Analysis</h6>\n              <div class="metric-subtitle">\n                Average property price: <strong>${n(p)}</strong><br>\n                Agency commission rate: <strong>${e(d)}</strong><br>\n                Gross commission per deal: <strong>${n(R)}</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card ${B>0?"success":"warning"}">\n              <h6>📈 Profitability Forecast</h6>\n              <div class="metric-subtitle">\n                Annual profit: <strong>${n(F)}</strong><br>\n                Weekly profit: <strong>${n(F/52)}</strong><br>\n                Daily profit: <strong>${n(F/365)}</strong>\n              </div>\n            </div>\n            <div class="insight-card info">\n              <h6>💡 Growth Potential</h6>\n              <div class="metric-subtitle">\n                +1 deal/month impact: <strong>+${n(12*C)}/year</strong><br>\n                +1 agent potential: <strong>+${n(M-12*m/i)}/year</strong><br>\n                +0.5% commission rate: <strong>+${n(.5*p/100*c*12)}/year</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="recommendations">\n            <h4>🎯 Optimization Recommendations</h4>\n            <ul>\n              ${D<20?"<li>⚠️ Low profitability. Consider increasing commission rates or reducing agent costs.</li>":""}\n              ${L<2?"<li>📍 Low agent productivity. Improve training or motivation systems.</li>":""}\n              ${x>2?"<li>⏰ Long payback period. Optimize startup costs or increase deal volume.</li>":""}\n              ${L>4?"<li>✅ High productivity! Consider team expansion or commission increases.</li>":""}\n              ${D>35?"<li>🎉 Excellent profitability! Consider opening additional offices.</li>":""}\n              <li>💼 Implement CRM system for effective client and deal management.</li>\n              <li>📱 Develop online presence: website, social media, digital advertising.</li>\n              <li>🎯 Specialize in profitable segments: commercial real estate, new developments.</li>\n              <li>🤝 Build partnerships with developers, banks, insurance companies.</li>\n              <li>📈 Implement KPI system for agents: deal count, sales volume, service quality.</li>\n              <li>⭐ Invest in staff training and professional development.</li>\n              <li>🎪 Consider additional services: valuation, legal support, mortgage assistance.</li>\n              <li>🌐 Leverage technology: virtual tours, automated marketing, document management.</li>\n              <li>💳 Develop referral programs and client retention strategies.</li>\n            </ul>\n          </div>\n\n          <div class="print-section">\n            <button onclick="window.print()" class="print-btn">🖨️ Print Business Plan</button>\n            <button onclick="downloadCSV()" class="download-btn">📥 Download Data (CSV)</button>\n          </div>\n        </div>\n      `,window.realEstateBusinessData={"Number of Agents":i,"Total Investment ($)":y,"Annual Agency Revenue ($)":I,"Annual Expenses ($)":A,"Annual Profit ($)":F,"Monthly Profit ($)":B,"Profit Margin (%)":D,"Annual ROI (%)":P,"Payback Period (years)":x,"Monthly Deals":c,"Deals per Agent":L,"Agency Commission (%)":d,"Revenue per Agent ($)":M}}),window.downloadCSV=function(){if(!window.realEstateBusinessData)return;const n=Object.entries(window.realEstateBusinessData).map(([n,e])=>`"${n}","${"number"==typeof e?e.toFixed(2):e}"`).join("\n"),e=new Blob(["\ufeffMetric,Value\n"+n],{type:"text/csv;charset=utf-8;"}),s=document.createElement("a");s.href=URL.createObjectURL(e),s.download="real-estate-agency-business-plan.csv",s.click()}});